code.cpp:
class Solution {
public:
    int longestSubsequence(string s, int k) {
        int n = s.size();
        long long value = 0;
        int length = 0;
        for (int i = n - 1; i >= 0; i--) {
            if (s[i] == '0') {
                length++;
            } else {
                if (length < 31) {
                    long long add = 1LL << length;
                    if (value + add <= k) {
                        value += add;
                        length++;
                    }
                }
            }
        }
        return length;
    }
};
